use std::io

fn convert(value: string, from: int, to: int) -> string {
    let digits: Vec<char> = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect()
    let mut n: int = 0
    for c in value.chars() {
        let d = c.to_digit(36) ?? 0
        n = n * from + d
    }
    if n == 0 {
        return "0"
    }
    let mut out: Vec<char> = Vec::new()
    while n > 0 {
        out.push(digits[n % to])
        n = n / to
    }
    let mut s = ""
    let mut i = out.len()
    while i > 0 {
        i = i - 1
        s = s + out[i].to_string()
    }
    s
}

fn main() {
    loop {
        let r = io::read_line()
        match r {
            Ok(line) => {
                let parts = line.trim().split_whitespace().collect::<Vec<string>>()
                if line.len() == 0 {
                    break
                }
                if parts.len() >= 3 {
                    let from = parts[1].parse::<int>() ?? 10
                    let to = parts[2].parse::<int>() ?? 10
                    println(convert(parts[0].to_uppercase(), from, to))
                }
            }
            Err(_) => {
                break
            }
        }
    }
}

